import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { describe, expect, it, vi } from 'vitest'
import { IssueCard } from '../components/IssueCard'
import type { Issue } from '../types'
import { makeIssue } from './fakeApi'

const issue: Issue = makeIssue(7, {
  _id: 'abc',
  title: 'Login button does nothing',
  status: 'in-progress',
  priority: 'high',
})

describe('IssueCard', () => {
  it('shows the title as a heading', () => {
    render(<IssueCard issue={issue} />)
    expect(screen.getByRole('heading', { name: 'Login button does nothing' })).toBeInTheDocument()
  })

  it('shows the status', () => {
    render(<IssueCard issue={issue} />)
    expect(screen.getByText('in-progress')).toBeInTheDocument()
  })

  it('shows the priority', () => {
    render(<IssueCard issue={issue} />)
    expect(screen.getByText('Priority: high')).toBeInTheDocument()
  })

  it('shows who reported the issue', () => {
    render(<IssueCard issue={issue} />)
    expect(screen.getByText('Reported by Eve Developer')).toBeInTheDocument()
  })

  it('has no View button when onSelect is not given', () => {
    render(<IssueCard issue={issue} />)
    expect(screen.queryByRole('button', { name: 'View' })).not.toBeInTheDocument()
  })

  it('calls onSelect with the issue _id when View is clicked', async () => {
    const onSelect = vi.fn()
    render(<IssueCard issue={issue} onSelect={onSelect} />)
    await userEvent.click(screen.getByRole('button', { name: 'View' }))
    expect(onSelect).toHaveBeenCalledTimes(1)
    expect(onSelect).toHaveBeenCalledWith('abc')
  })

  it('renders each issue it is given, not a fixed one', () => {
    render(<IssueCard issue={{ ...issue, title: 'Another title', priority: 'low' }} />)
    expect(screen.getByRole('heading', { name: 'Another title' })).toBeInTheDocument()
    expect(screen.getByText('Priority: low')).toBeInTheDocument()
  })
})

// These checks are for TypeScript, not for the browser. They only pass
// `npx tsc --noEmit -p tsconfig.app.json` when your types reject the wrong shapes.
describe('IssueCard types', () => {
  it('rejects a status that is not one of the three allowed values', () => {
    // @ts-expect-error "done" is not an allowed status
    const bad: Issue = { ...issue, status: 'done' }
    void bad
  })

  it('rejects an issue that uses id instead of _id', () => {
    // @ts-expect-error the API calls it _id, and TypeScript should say so
    const bad: Issue = { ...issue, id: 'abc' }
    void bad
  })

  it('requires the issue prop', () => {
    // @ts-expect-error the issue prop is required
    const element = <IssueCard />
    void element
  })

  it('only lets onSelect be a function', () => {
    // @ts-expect-error onSelect must be a function, not a string
    const element = <IssueCard issue={issue} onSelect="nope" />
    void element
  })
})
